const clone=v=>structuredClone(v),round=n=>Math.round(n*1000)/1000;
export const segmentDistance=(p,a,b)=>{const dx=b[0]-a[0],dy=b[1]-a[1],t=Math.max(0,Math.min(1,((p[0]-a[0])*dx+(p[1]-a[1])*dy)/(dx*dx+dy*dy||1)));return {distance:Math.hypot(p[0]-a[0]-t*dx,p[1]-a[1]-t*dy),point:[a[0]+t*dx,a[1]+t*dy]};};
