  controls.querySelectorAll('[data-pick-remove-room]').forEach(b=>b.onclick=()=>{selected=selected.filter(s=>s.roomId!==b.dataset.pickRemoveRoom);if(focused?.id===b.dataset.pickRemoveRoom)focused=null;render();});
